package me.raddatz.veyq.core.crypto

import com.fasterxml.jackson.databind.JsonNode
import com.fasterxml.jackson.databind.ObjectMapper
import org.junit.jupiter.api.Assertions.assertArrayEquals
import org.junit.jupiter.api.Assertions.assertFalse
import org.junit.jupiter.api.Assertions.assertNull
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test
import java.io.File
import java.util.Base64
import java.util.HexFormat

/**
 * The backend's key-chain statements and heads are the contract's (`key_chain` in the crypto vectors, generated by an
 * independent Python implementation and asserted by `packages/crypto`'s `verifyKeyChain` too). The server rebuilds a
 * published step from the stored head and keys and checks both signatures, so a drift is every account's rotation
 * refused — this reddens first. Each failure case of the vector is refused by the half it names, and only by it.
 */
class KeyChainStepTest {

    private val v: JsonNode = ObjectMapper().readTree(File("../../contracts/crypto/vectors/v1.json"))["key_chain"]
    private val userId = v["user_id"].asText()
    private val links = v["links"]

    @Test
    fun theGenesisIsTheVectorsAndItsHeadToo() {
        val g = links[0]
        val stmt = KeyChainStatements.genesis(userId, b64(g["identity_public_key"]), b64(g["secret_key_proof_public_key"]))
        assertArrayEquals(hex(g["statement"]), stmt)
        assertArrayEquals(hex(g["head"]), KeyChainStatements.head(stmt!!))
    }

    @Test
    fun eachStepIsTheVectorsItsHeadToo_AndBothHalvesVerifyUnderTheKeysItRetires() {
        for (i in 1..2) {
            val step = links[i]
            val prev = links[i - 1]
            val stmt = stepStatement(step, prev)
            assertArrayEquals(hex(step["statement"]), stmt, "step $i")
            assertArrayEquals(hex(step["head"]), KeyChainStatements.head(stmt!!), "step $i head")
            assertArrayEquals(hex(prev["head"]), hex(step["previous_head"]), "step $i names its predecessor's head")
            assertTrue(KeyChainStatements.identityHalfVerifies(b64(prev["identity_public_key"]), stmt, b64(step["identity_signature"])), "step $i identity")
            assertTrue(KeyChainStatements.proofHalfVerifies(b64(prev["secret_key_proof_public_key"]), stmt, b64(step["proof_signature"])), "step $i proof")
        }
    }

    @Test
    fun eachFailureIsRefusedByTheHalfItNames() {
        val prev = links[1]
        val f = v["failures"]
        // The server rebuilds step 2 from the STORED head (step 1's), never the one a request would name.
        val rebuilt = stepStatement(links[2], prev)

        val wrongPredecessor = f["wrong_predecessor"]
        assertFalse(KeyChainStatements.identityHalfVerifies(b64(prev["identity_public_key"]), rebuilt, b64(wrongPredecessor["identity_signature"])),
            "a step signed over a stale predecessor fails the rebuilt statement")
        assertFalse(KeyChainStatements.proofHalfVerifies(b64(prev["secret_key_proof_public_key"]), rebuilt, b64(wrongPredecessor["proof_signature"])))

        val byOtherIdentity = f["identity_signature_by_another_key"]
        assertFalse(KeyChainStatements.identityHalfVerifies(b64(prev["identity_public_key"]), rebuilt, b64(byOtherIdentity["identity_signature"])))
        assertTrue(KeyChainStatements.proofHalfVerifies(b64(prev["secret_key_proof_public_key"]), rebuilt, b64(byOtherIdentity["proof_signature"])),
            "only the identity half fails")

        val byOtherProof = f["proof_signature_by_another_key"]
        assertTrue(KeyChainStatements.identityHalfVerifies(b64(prev["identity_public_key"]), rebuilt, b64(byOtherProof["identity_signature"])),
            "only the proof half fails")
        assertFalse(KeyChainStatements.proofHalfVerifies(b64(prev["secret_key_proof_public_key"]), rebuilt, b64(byOtherProof["proof_signature"])))
    }

    @Test
    fun aSignatureByTheNewKeysIsNotAStep() {
        // A step is signed by what it RETIRES: the new identity and proof key signing their own installation prove nothing.
        val step = links[2]
        val stmt = stepStatement(step, links[1])
        assertFalse(KeyChainStatements.identityHalfVerifies(b64(step["identity_public_key"]), stmt, b64(step["identity_signature"])))
        assertFalse(KeyChainStatements.proofHalfVerifies(b64(step["secret_key_proof_public_key"]), stmt, b64(step["proof_signature"])))
    }

    @Test
    fun everyMalformedInputIsARefusalNeverAnException() {
        val prev = links[1]
        val step = links[2]
        val head = hex(prev["head"])
        assertNull(KeyChainStatements.step(userId, 0, head, b64(prev["identity_public_key"]), b64(prev["secret_key_proof_public_key"]), b64(step["identity_public_key"]), b64(step["secret_key_proof_public_key"])), "index 0 is the genesis")
        assertNull(KeyChainStatements.step(userId, 2, head.copyOf(31), b64(prev["identity_public_key"]), b64(prev["secret_key_proof_public_key"]), b64(step["identity_public_key"]), b64(step["secret_key_proof_public_key"])), "a head that is no digest")
        assertNull(KeyChainStatements.genesis(userId.uppercase(), "AQ==", "AQ=="), "a non-canonical id")
        assertNull(KeyChainStatements.genesis(userId, "not base64 !", "AQ=="))
        val stmt = stepStatement(step, prev)
        assertFalse(KeyChainStatements.proofHalfVerifies(null, stmt, b64(step["proof_signature"])), "an account with no proof key")
        assertFalse(KeyChainStatements.identityHalfVerifies(b64(prev["identity_public_key"]), stmt, "not base64 !"))
        assertFalse(KeyChainStatements.identityHalfVerifies(b64(prev["identity_public_key"]), null, b64(step["identity_signature"])))
    }

    private fun stepStatement(step: JsonNode, prev: JsonNode) = KeyChainStatements.step(
        userId, step["index"].asLong(), hex(prev["head"]),
        b64(prev["identity_public_key"]), b64(prev["secret_key_proof_public_key"]),
        b64(step["identity_public_key"]), b64(step["secret_key_proof_public_key"]),
    )

    private fun hex(n: JsonNode): ByteArray = HexFormat.of().parseHex(n.asText())
    private fun b64(n: JsonNode): String = Base64.getEncoder().encodeToString(hex(n))
}
